# Location extraction and raw logo helper for SpotNews clippings
RAW_LOGO_DATA_URI = "data:image/png;base64,"

import re

def clean_html(s):
    if not s: return ''
    s = re.sub(r'<[^>]+>', ' ', str(s))
    s = s.replace('&nbsp;', ' ').replace('&quot;', '"').replace('&#39;', "'").replace('&amp;', '&')
    s = re.sub(r'[\u00a0\u200b\ufeff]', ' ', s)
    s = re.sub(r'[\r\n\t\v\f]+', ' ', s)
    return re.sub(r'\s+', ' ', s).strip()

def extract_exact_location(data):
    cl = data.get('custom_layout') or {}
    if isinstance(cl, str):
        try:
            import json
            cl = json.loads(cl)
        except Exception:
            cl = {}

    candidates = [
        data.get('pinpoint'), cl.get('pinpoint'),
        data.get('exact_location'), cl.get('exact_location'), cl.get('exactLocation'),
        data.get('mandal'), cl.get('mandal'),
        data.get('village'), cl.get('village'),
        data.get('area'), cl.get('area'),
        data.get('town'), cl.get('town'),
        data.get('city'), cl.get('city'),
        data.get('place'), cl.get('place'),
        data.get('location'), cl.get('location'),
    ]
    ignored = re.compile(r'^(all|all\s*districts|all\s*mandals|rti\s*express|ఆంధ్రప్రదేశ్|తెలంగాణ|అన్ని|అన్ని\s*జిల్లాలు|అన్ని\s*మండలాలు)$', re.I)
    for c in candidates:
        if c and isinstance(c, str):
            t = c.strip()
            if t and not ignored.match(t):
                return t

    headline = clean_html(data.get('headline') or cl.get('headline') or '')
    subheadline = clean_html(data.get('subheadline') or cl.get('subheadline') or '')
    raw_body = clean_html(data.get('article_content') or cl.get('articleContent') or cl.get('article_content') or data.get('content') or '')
    body_text = f'{subheadline} {raw_body}' if subheadline and not raw_body.startswith(subheadline) else raw_body

    TELUGU_CHAR = r'[A-Za-z0-9\u0C00-\u0C7F\u200C\u200D]'

    if headline:
        admin_match = re.search(r'(?:^|["\'\s:–—])(' + TELUGU_CHAR + r'{2,24})\s+(?:మేజర్\s+గ్రామపంచాయతీ|గ్రామపంచాయతీ|పంచాయతీ|మండలం|మున్సిపాలిటీ|గ్రామం)(?:లో| పరిధిలో)?', headline)
        if admin_match:
            loc = admin_match.group(1).strip()
            if not re.match(r'^(ఈ|ఆ|సదరు|స్థానిక|గ్రామ|మేజర్)$', loc):
                return loc

        loc_in_match = re.search(r'(?:^|["\'\s:–—])(' + TELUGU_CHAR + r'{2,24})లో(?:\s|$)', headline)
        if loc_in_match:
            cand = loc_in_match.group(1).strip()
            non_loc = re.compile(r'^(ఇందు|అందు|ఇలాంటి|సమయం|సందర్భం|నేపథ్యం|రాజకీయం|విధానం|రంగం|పరిస్థితు|పరిస్థితుల్లో|ఫలితం|వరుస|విషయం|మధ్య|చివరి|మొదటి|తాజా|దేశం|రాష్ట్రం|జిల్లా|ప్రపంచం)$')
            if not non_loc.match(cand) and len(cand) >= 2:
                return cand

        loc_vadda = re.search(r'(?:^|["\'\s:–—])(' + TELUGU_CHAR + r'{2,24})\s+వద్ద(?:\s|$)', headline)
        if loc_vadda:
            return loc_vadda.group(1).strip()

    if body_text:
        paren = re.search(r'^\s*(' + TELUGU_CHAR + r'{2,24}\s*\([A-Za-z0-9\u0C00-\u0C7F\u200C\u200D\s]{2,28}\))\s*[:–—\-]', body_text)
        if paren:
            return paren.group(1).strip()

        staffer = re.search(r'^\s*(' + TELUGU_CHAR + r'{2,24})\s+(?:జిల్లా\s+స్టాఫర్|స్టాఫ్\s*రిపోర్టర్|విలేకరి|ప్రతినిధి|బ్యూరో)', body_text, re.I)
        if staffer:
            p = staffer.group(1).strip()
            if len(p) >= 2 and not re.match(r'^(మన|ఈ|ప్రత్యేక|ముఖ్య)$', p):
                return p

        date_loc = re.search(r'^\s*(' + TELUGU_CHAR + r'{2,24})\s*,\s*(?:నవంబర్|డిసెంబర్|జనవరి|ఫిబ్రవరి|మార్చి|ఏప్రిల్|మే|జూన్|జూలై|ఆగస్టు|సెప్టెంబర్|అక్టోబర్|నవంబరు|డిసెంబరు|\d{1,2})', body_text, re.I)
        if date_loc:
            return date_loc.group(1).strip()

        simple = re.search(r'^\s*(' + TELUGU_CHAR + r'{2,24})\s*[:–—\-]', body_text)
        if simple:
            loc = simple.group(1).strip()
            not_loc = re.compile(r'^(గమనిక|ముఖ్య|నోట్|update|breaking|నవంబర్|డిసెంబర్|జనవరి|ఫిబ్రవరి|మార్చి|ఏప్రిల్|మే|జూన్|జూలై|ఆగస్టు|సెప్టెంబర్|అక్టోబర్|సోమవారం|మంగళవారం|బుధవారం|గురువారం|శుక్రవారం|శనివారం|ఆదివారం)$', re.I)
            if not not_loc.match(loc) and len(loc) >= 2:
                return loc

        body_village = re.search(r'(' + TELUGU_CHAR + r'{2,24})\s+(?:మేజర్\s+గ్రామపంచాయతీ|గ్రామపంచాయతీ|పంచాయతీ|మండలం|మున్సిపాలిటీ)(?:లోని| పరిధిలోని|లో)?', body_text)
        if body_village:
            loc = body_village.group(1).strip()
            if not re.match(r'^(ఈ|ఆ|సదరు|స్థానిక|గ్రామ|మేజర్)$', loc):
                return loc

    dist = data.get('district') or cl.get('district')
    if dist and isinstance(dist, str) and dist.strip() and not re.match(r'^(all|all\s*districts|అన్ని\s*జిల్లాలు)$', dist.strip(), re.I):
        return dist.strip()

    state = data.get('state') or cl.get('state')
    if state and isinstance(state, str) and state.strip() and not re.match(r'^(all)$', state.strip(), re.I):
        return state.strip()

    return 'ఆంధ్రప్రదేశ్'
